import { LIMITS } from "./store.js";

export function escapeHtml(value) {
  return String(value)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

const styles = `
  body { font: 16px/1.5 system-ui, sans-serif; max-width: 40rem; margin: 2rem auto; padding: 0 1rem; color: #222; }
  h1 a { color: inherit; text-decoration: none; }
  ul { padding: 0; list-style: none; }
  li { display: flex; justify-content: space-between; align-items: center; gap: 1rem; padding: .5rem 0; border-bottom: 1px solid #eee; }
  .muted { color: #666; }
  form.inline { margin: 0; }
  label { display: block; margin-top: .75rem; }
  input[type=text], textarea { width: 100%; box-sizing: border-box; padding: .4rem; font: inherit; }
  textarea { min-height: 6rem; }
  button { font: inherit; padding: .3rem .8rem; cursor: pointer; }
  .error { color: #b00020; font-size: .9rem; }
  .notes { white-space: pre-wrap; background: #f7f7f7; padding: .75rem; border-radius: 4px; }
`;

function layout(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escapeHtml(title)}</title>
<style>${styles}</style>
</head>
<body>
<h1><a href="/">My books</a></h1>
${body}
</body>
</html>`;
}

function finishButton(book) {
  return `<form class="inline" method="post" action="/books/${book.id}/finish">
    <button type="submit">Mark finished</button>
  </form>`;
}

function bookLink(book) {
  return `<a href="/books/${book.id}">${escapeHtml(book.title)}</a>
    <span class="muted">by ${escapeHtml(book.author)}</span>`;
}

export function homePage(books, { values = {}, errors = {} } = {}) {
  const reading = books.filter((b) => b.status === "reading");
  const finished = books
    .filter((b) => b.status === "finished")
    .sort((a, b) => b.finishedAt.localeCompare(a.finishedAt));

  const readingList = reading.length
    ? `<ul>${reading.map((b) => `<li><span>${bookLink(b)}</span>${finishButton(b)}</li>`).join("")}</ul>`
    : `<p class="muted">Nothing on the go. Add a book below.</p>`;

  const finishedList = finished.length
    ? `<ul>${finished.map((b) => `<li><span>${bookLink(b)}</span><span class="muted">${formatDate(b.finishedAt)}</span></li>`).join("")}</ul>`
    : `<p class="muted">No finished books yet.</p>`;

  const field = (name, label, input) => `
    <label for="${name}">${label}</label>
    ${input}
    ${errors[name] ? `<div class="error">${escapeHtml(errors[name])}</div>` : ""}`;
  const v = (name) => escapeHtml(values[name] ?? "");

  return layout(
    "My books",
    `<h2>Currently reading</h2>
${readingList}
<h2>Finished</h2>
${finishedList}
<h2 id="add">Add a book</h2>
<form method="post" action="/books">
  ${field("title", "Title", `<input type="text" id="title" name="title" required maxlength="${LIMITS.title}" value="${v("title")}">`)}
  ${field("author", "Author", `<input type="text" id="author" name="author" required maxlength="${LIMITS.author}" value="${v("author")}">`)}
  ${field("notes", "Notes <span class=\"muted\">(optional)</span>", `<textarea id="notes" name="notes" maxlength="${LIMITS.notes}">${v("notes")}</textarea>`)}
  <p><button type="submit">Add book</button></p>
</form>`,
  );
}

export function bookPage(book) {
  const status =
    book.status === "finished"
      ? `<p class="muted">Finished ${formatDate(book.finishedAt)}</p>`
      : `<p class="muted">Currently reading</p>${finishButton(book)}`;
  const notes = book.notes
    ? `<div class="notes">${escapeHtml(book.notes)}</div>`
    : `<p class="muted">No notes.</p>`;

  return layout(
    book.title,
    `<h2>${escapeHtml(book.title)}</h2>
<p>by ${escapeHtml(book.author)}</p>
${status}
<h3>Notes</h3>
${notes}
<p><button type="button" id="copy">Copy link to this book</button> <span id="copied" class="muted"></span></p>
<p><a href="/">&larr; All books</a></p>
<script>
  document.getElementById("copy").addEventListener("click", async () => {
    const out = document.getElementById("copied");
    try {
      await navigator.clipboard.writeText(location.href);
      out.textContent = "Copied.";
    } catch {
      out.textContent = location.href;
    }
  });
</script>`,
  );
}

export function notFoundPage() {
  return layout(
    "Not found",
    `<p>That book doesn't exist (or was never added here).</p><p><a href="/">&larr; All books</a></p>`,
  );
}

function formatDate(iso) {
  return new Date(iso).toLocaleDateString("en-US", {
    year: "numeric",
    month: "short",
    day: "numeric",
  });
}

