import { mkdir, readFile, rename, writeFile } from "node:fs/promises";
import { dirname } from "node:path";

export const LIMITS = { title: 200, author: 200, notes: 5000 };

// Books live in a single JSON file. Every change rewrites the whole file via a
// temp file + rename, so a crash mid-write never leaves a half-written file.
export async function createStore(filePath) {
  let books = await load(filePath);
  let queue = Promise.resolve();

  function persist() {
    const snapshot = JSON.stringify({ books }, null, 2) + "\n";
    // Serialize writes so two quick requests can't interleave on disk.
    queue = queue.then(async () => {
      await mkdir(dirname(filePath), { recursive: true });
      const tmp = `${filePath}.${process.pid}.tmp`;
      await writeFile(tmp, snapshot);
      await rename(tmp, filePath);
    });
    return queue;
  }

  return {
    list() {
      return books.slice();
    },

    get(id) {
      return books.find((b) => b.id === id) ?? null;
    },

    async add(input) {
      const { book, errors } = validate(input);
      if (errors) return { errors };
      book.id = newId(books);
      book.status = "reading";
      book.addedAt = new Date().toISOString();
      book.finishedAt = null;
      books.push(book);
      await persist();
      return { book };
    },

    async finish(id) {
      const book = books.find((b) => b.id === id);
      if (!book) return null;
      if (book.status !== "finished") {
        book.status = "finished";
        book.finishedAt = new Date().toISOString();
        await persist();
      }
      return book;
    },
  };
}

async function load(filePath) {
  let text;
  try {
    text = await readFile(filePath, "utf8");
  } catch (err) {
    if (err.code === "ENOENT") return [];
    throw err;
  }
  // A corrupt file is surfaced rather than silently replaced with an empty
  // list, which would wipe the user's books on the next save.
  const data = JSON.parse(text);
  if (!Array.isArray(data.books)) {
    throw new Error(`${filePath}: expected {"books": [...]}`);
  }
  return data.books;
}

export function validate(input) {
  const book = {
    title: String(input.title ?? "").trim(),
    author: String(input.author ?? "").trim(),
    notes: String(input.notes ?? "").trim(),
  };
  const errors = {};
  if (!book.title) errors.title = "Title is required.";
  if (!book.author) errors.author = "Author is required.";
  for (const [field, max] of Object.entries(LIMITS)) {
    if (book[field].length > max) {
      errors[field] = `Keep this under ${max} characters.`;
    }
  }
  return Object.keys(errors).length ? { book, errors } : { book };
}

function newId(books) {
  let id;
  do id = randomBytes(5).toString("hex");
  while (books.some((b) => b.id === id));
  return id;
}

import { bookPage, homePage, notFoundPage } from "./views.js";

const MAX_BODY_BYTES = 64 * 1024;

export function createHandler(store) {
  return async function handle(req, res) {
    try {
      await route(store, req, res);
    } catch (err) {
      if (err.status === 413) return send(res, 413, "Request too large");
      console.error(err);
      send(res, 500, "Something went wrong");
    }
  };
}

async function route(store, req, res) {
  const { pathname } = new URL(req.url, "http://localhost");
  const method = req.method;

  if (pathname === "/") {
    if (method !== "GET" && method !== "HEAD") return notAllowed(res, "GET");
    return html(res, 200, homePage(store.list()));
  }

  if (pathname === "/books") {
    if (method !== "POST") return notAllowed(res, "POST");
    const form = await readForm(req);
    const result = await store.add(form);
    if (result.errors) {
      // Re-show the form with what the user typed so nothing is lost.
      return html(res, 400, homePage(store.list(), { values: form, errors: result.errors }));
    }
    return redirect(res, `/books/${result.book.id}`);
  }

  let m = pathname.match(/^\/books\/([a-z0-9]+)$/);
  if (m) {
    if (method !== "GET" && method !== "HEAD") return notAllowed(res, "GET");
    const book = store.get(m[1]);
    return book ? html(res, 200, bookPage(book)) : html(res, 404, notFoundPage());
  }

  m = pathname.match(/^\/books\/([a-z0-9]+)\/finish$/);
  if (m) {
    if (method !== "POST") return notAllowed(res, "POST");
    const book = await store.finish(m[1]);
    if (!book) return html(res, 404, notFoundPage());
    return redirect(res, safeBack(req) ?? "/");
  }

  html(res, 404, notFoundPage());
}

// Send the user back to the page they clicked "Mark finished" on, but only
// if it's a page on this site.
function safeBack(req) {
  const ref = req.headers.referer;
  if (!ref) return null;
  try {
    const url = new URL(ref);
    if (url.host !== req.headers.host) return null;
    return url.pathname;
  } catch {
    return null;
  }
}

async function readForm(req) {
  let size = 0;
  const chunks = [];
  for await (const chunk of req) {
    size += chunk.length;
    if (size > MAX_BODY_BYTES) {
      throw Object.assign(new Error("body too large"), { status: 413 });
    }
    chunks.push(chunk);
  }
  return Object.fromEntries(new URLSearchParams(Buffer.concat(chunks).toString("utf8")));
}

function html(res, status, body) {
  res.writeHead(status, { "Content-Type": "text/html; charset=utf-8" });
  res.end(body);
}

function send(res, status, text) {
  if (res.headersSent) return res.end();
  res.writeHead(status, { "Content-Type": "text/plain; charset=utf-8" });
  res.end(text);
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

function notAllowed(res, allow) {
  res.writeHead(405, { Allow: allow, "Content-Type": "text/plain; charset=utf-8" });
  res.end("Method not allowed");
}

import { createServer } from "node:http";
import { resolve } from "node:path";
import { createHandler } from "./src/app.js";
import { createStore } from "./src/store.js";

const port = Number(process.env.PORT ?? 3000);
const host = process.env.HOST ?? "127.0.0.1";
const dataFile = resolve(process.env.DATA_FILE ?? "data/books.json");

const store = await createStore(dataFile);
createServer(createHandler(store)).listen(port, host, () => {
  console.log(`Books app on http://${host}:${port} (saving to ${dataFile})`);
});

