import { createServer } from "node:http";
import { mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { createHandler } from "../src/app.js";
import { createStore } from "../src/store.js";

let dir, dataFile, server, base;

async function start() {
  const store = await createStore(dataFile);
  server = createServer(createHandler(store));
  await new Promise((r) => server.listen(0, "127.0.0.1", r));
  base = `http://127.0.0.1:${server.address().port}`;
}

async function stop() {
  await new Promise((r) => server.close(r));
}

function post(path, fields = {}, headers = {}) {
  return fetch(base + path, {
    method: "POST",
    body: new URLSearchParams(fields),
    redirect: "manual",
    headers,
  });
}

async function addBook(fields) {
  const res = await post("/books", fields);
  expect(res.status).toBe(303);
  return res.headers.get("location");
}

beforeEach(async () => {
  dir = await mkdtemp(join(tmpdir(), "books-"));
  dataFile = join(dir, "books.json");
  await start();
});

afterEach(async () => {
  await stop();
  await rm(dir, { recursive: true, force: true });
});

describe("books app", () => {
  it("shows empty sections on first open", async () => {
    const html = await (await fetch(base + "/")).text();
    expect(html).toContain("Currently reading");
    expect(html).toContain("Nothing on the go");
    expect(html).toContain("No finished books yet");
  });

  it("adds a book and gives it its own page", async () => {
    const location = await addBook({ title: "Dune", author: "Frank Herbert", notes: "Spice.\nSand." });
    expect(location).toMatch(/^\/books\/[a-z0-9]+$/);

    const page = await fetch(base + location);
    expect(page.status).toBe(200);
    const html = await page.text();
    expect(html).toContain("Dune");
    expect(html).toContain("by Frank Herbert");
    expect(html).toContain("Spice.\nSand.");

    const home = await (await fetch(base + "/")).text();
    const reading = home.split("<h2>Finished</h2>")[0];
    expect(reading).toContain(`href="${location}"`);
  });

  it("moves a book to Finished", async () => {
    const location = await addBook({ title: "Emma", author: "Jane Austen" });
    const res = await post(`${location}/finish`, {}, { referer: `${base}/` });
    expect(res.status).toBe(303);
    expect(res.headers.get("location")).toBe("/");

    const home = await (await fetch(base + "/")).text();
    const [reading, finished] = home.split("<h2>Finished</h2>");
    expect(reading).not.toContain("Emma");
    expect(finished).toContain("Emma");
    expect(await (await fetch(base + location)).text()).toContain("Finished ");
  });

  it("does not redirect finish to another site", async () => {
    const location = await addBook({ title: "Emma", author: "Jane Austen" });
    const res = await post(`${location}/finish`, {}, { referer: "https://evil.example/x" });
    expect(res.headers.get("location")).toBe("/");
  });

  it("keeps books after a restart", async () => {
    const location = await addBook({ title: "Middlemarch", author: "George Eliot", notes: "Long." });
    await post(`${location}/finish`);
    await stop();
    await start();

    const html = await (await fetch(base + location)).text();
    expect(html).toContain("Middlemarch");
    expect(html).toContain("Long.");
    expect(html).toContain("Finished ");

    const saved = JSON.parse(await readFile(dataFile, "utf8"));
    expect(saved.books).toHaveLength(1);
  });

  it("rejects a missing title and keeps what was typed", async () => {
    const res = await post("/books", { title: "  ", author: "Someone", notes: "keep me" });
    expect(res.status).toBe(400);
    const html = await res.text();
    expect(html).toContain("Title is required.");
    expect(html).toContain('value="Someone"');
    expect(html).toContain("keep me");
    expect(JSON.parse(await readFile(dataFile, "utf8").catch(() => '{"books":[]}')).books).toHaveLength(0);
  });

  it("escapes HTML in user input", async () => {
    const location = await addBook({ title: "<script>alert(1)</script>", author: "A & B" });
    const html = await (await fetch(base + location)).text();
    expect(html).not.toContain("<script>alert(1)</script>");
    expect(html).toContain("&lt;script&gt;");
    expect(html).toContain("A &amp; B");
  });

  it("returns 404 for unknown books", async () => {
    expect((await fetch(base + "/books/nope123")).status).toBe(404);
    expect((await post("/books/nope123/finish")).status).toBe(404);
  });

  it("refuses to start over a corrupt data file instead of wiping it", async () => {
    await writeFile(dataFile, "{not json");
    await expect(createStore(dataFile)).rejects.toThrow();
    expect(await readFile(dataFile, "utf8")).toBe("{not json");
  });
});

